import copy

__all__ = ["merge"]


def merge(base: dict, override: dict) -> dict:
    """Deep-merge ``override`` into ``base`` and return a new dictionary.

    Args:
        base: Dictionary that provides the default values.
        override: Dictionary whose values take precedence over ``base``.
            A key whose value is ``None`` is removed from the result.

    Returns:
        A new dictionary. Neither ``base`` nor ``override`` is mutated,
        and the result shares no mutable objects with either input.

    Raises:
        ValueError: If ``base`` or ``override`` is not a ``dict``.

    Examples:
        >>> merge({'a': {'b': 1, 'c': 2}}, {'a': {'c': 3}})
        {'a': {'b': 1, 'c': 3}}
        >>> merge({'a': 1}, {'a': None})
        {}
    """
    if not isinstance(base, dict):
        raise ValueError(f"'base' must be a dict, got {type(base).__name__}")
    if not isinstance(override, dict):
        raise ValueError(f"'override' must be a dict, got {type(override).__name__}")

    # Start from a fully independent copy of base.
    result = {key: copy.deepcopy(value) for key, value in base.items()}
    for key, value in override.items():
        _merge_entry(result, key, value)
    return result


def _merge_entry(result: dict, key, value) -> None:
    """Fold one ``key: value`` entry of the override into ``result`` (in place)."""
    if value is None:
        result.pop(key, None)
    elif isinstance(value, dict) and isinstance(result.get(key), dict):
        # dict-on-dict: merge recursively.
        result[key] = _deep_merge(result[key], value)
    else:
        # Scalars and lists are replaced; copy to stay independent.
        result[key] = copy.deepcopy(value)


def _deep_merge(base: dict, override: dict) -> dict:
    """Merge ``override`` onto an already-independent ``base`` and return the result."""
    result = dict(base)
    for key, value in override.items():
        _merge_entry(result, key, value)
    return result
